        this._canvas = element;
        this._pointerDown = false;
        this._previousPosition = new Vector2(0, 0);
        this._previousPosition2 = new Vector2(0, 0);
        this._canvas.addEventListener("pointermove", this._pointerMoveObserver);
        this._canvas.addEventListener("pointerdown", this._pointerDownObserver);
        this._canvas.addEventListener("pointerup", this._pointerUpObserver);
