    _pointerDownObserver(evt: PointerEvent) {
        this._pointerDown = true;
        this._previousPosition.x = evt.clientX;
        this._previousPosition.y = evt.clientY;
    }
    _pointerUpObserver(evt: PointerEvent) {
        this._pointerDown = false;
    }
}
